import 'package:flutter/material.dart' hide Text;
import '../widgets/text.dart';
import 'package:intl/intl.dart';
import 'package:provider/provider.dart';
import '../state/app_state.dart';
import '../widgets/common.dart';
import '../widgets/ui.dart';

/// Message center: goal, streak and weekly-summary notices generated by the backend
/// (the local stand-in for push notifications).
class MessagesScreen extends StatefulWidget {
  const MessagesScreen({super.key});
  @override
  State<MessagesScreen> createState() => _MessagesScreenState();
}

class _MessagesScreenState extends State<MessagesScreen> {
  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) => context.read<AppState>().loadMessages());
  }

  IconData _icon(String k) => switch (k) { 'goal' => Icons.flag, 'streak' => Icons.local_fire_department, 'weekly' => Icons.insights, _ => Icons.notifications };

  @override
  Widget build(BuildContext context) {
    final s = context.watch<AppState>();
    return GScaffold(
      appBar: AppBar(title: const Text('Messages'), actions: [
        TextButton(onPressed: s.unread == 0 ? null : () => guarded(context, () => s.markMessagesRead()), child: const Text('Mark all read')),
      ]),
      body: s.messages.isEmpty
          ? const EmptyState(icon: Icons.notifications_none, text: 'No messages yet.\nGoal, streak and weekly summaries show up here.')
          : RefreshIndicator(
              onRefresh: s.loadMessages,
              child: ListView(padding: const EdgeInsets.only(top: 8, bottom: 24), children: [
                for (final m in s.messages)
                  Dismissible(
                    key: ValueKey(m['id']),
                    direction: DismissDirection.endToStart,
                    background: Container(color: Colors.red, alignment: Alignment.centerRight, padding: const EdgeInsets.only(right: 20), child: const Icon(Icons.delete, color: Colors.white)),
                    onDismissed: (_) => s.deleteMessage(m['id'] as int),
                    child: AppCard(
                      margin: const EdgeInsets.fromLTRB(16, 0, 16, 10),
                      onTap: () => s.markMessagesRead(id: m['id'] as int),
                      child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
                        CircleAvatar(backgroundColor: const Color(0xFFE3E7FD), child: Icon(_icon('${m['kind']}'), color: brandBlue)),
                        const SizedBox(width: 12),
                        Expanded(
                          child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
                            Row(children: [
                              Expanded(child: Text('${m['title']}', style: TextStyle(fontWeight: m['read'] == true ? FontWeight.w500 : FontWeight.w800))),
                              if (m['read'] != true) Container(width: 9, height: 9, decoration: const BoxDecoration(color: brandBlue, shape: BoxShape.circle)),
                            ]),
                            Text('${m['body']}', style: const TextStyle(fontSize: 13)),
                            Text(DateFormat('MMM d, HH:mm').format(DateTime.fromMillisecondsSinceEpoch((m['ts'] as num).toInt())), style: const TextStyle(fontSize: 11, color: mutedColor)),
                          ]),
                        ),
                      ]),
                    ),
                  ),
              ]),
            ),
    );
  }
}
